DROP TABLE ParametrosIpress;

CREATE TABLE ParametrosIpress(
	IdParametro int not null,
	IdIpress int not null,
	Tipo varchar(20),
	Codigo varchar(20),
	ValorTexto varchar(355),
	ValorInt int,
	ValorFloat float(53),
	ValorBinary VARBINARY(MAX),
	Descripcion varchar(150),
	Grupo varchar(30),
 CONSTRAINT PK_ParametrosIpress 
	PRIMARY KEY (IdParametro, IdIpress)
)
GO
 
--SELECT * FROM ParametrosIpress;
--SELECT * FROM ParametrosIpress WHERE IdParametro = 205  AND IdIpress = 2;

INSERT INTO ParametrosIpress(IdParametro,IdIpress,Tipo,Codigo,ValorTexto,ValorInt,ValorFloat,ValorBinary,Descripcion,Grupo)
SELECT
	p.IdParametro,i.IdIpress,p.Tipo,p.Codigo,p.ValorTexto,
	p.ValorInt,p.ValorFloat,null,p.Descripcion,p.Grupo
FROM Parametros p, Ipress i
GO

UPDATE ParametrosIpress SET ValorTexto = 'POLICLÍNICO NAVAL SAN BORJA' WHERE IdParametro = 205 AND IdIpress = 2;
UPDATE ParametrosIpress SET ValorTexto = 'AV FRAY ANGÉLICO 390, SAN BORJA' WHERE IdParametro = 206 AND IdIpress = 2;
UPDATE ParametrosIpress SET ValorTexto = '72523505' WHERE IdParametro = 207 AND IdIpress = 2;
UPDATE ParametrosIpress SET ValorTexto = 'MGP' WHERE IdParametro = 1007 AND IdIpress = 2;
GO


